-- ============================================================================
--  CP5 — Cenário C07 (golden set): tendência de alta de temperatura
--  Apaga as leituras das últimas 2h da MOTOR_01 e insere 24 amostras (5 em
--  5 min) com temperatura subindo de ~61°C a ~79°C, mantendo as demais
--  grandezas estáveis/nominais para isolar a tendência. Ganho ponta-a-ponta
--  de +29,5% (bem acima do limiar de 15% de
--  config/limiares.json::tendencia); como variacao_percentual (ver
--  v_tendencia_2h / consultar_historico) compara MÉDIAS de terços — robusto a
--  ruído, não só os 2 pontos extremos — o valor medido fica menor que o
--  ganho bruto (na prática ~19-20%, sempre acima de 15%; ver evidência de
--  validação do ticket T04).
--  O último ponto (~79°C) fica na faixa ATENÇÃO (70-80°C) do guardrail,
--  nunca CRÍTICO — o cenário espera "ATENÇÃO isolado" no guardrail e que o
--  especialista de Manutenção escale para CRÍTICO ao consultar a tendência.
--
--  Reutilizável pelo WF-90: chamado antes de rodar o cenário C07. Depois,
--  aplicar db/cenarios/reset_estavel.sql para voltar à linha de base.
--  Idempotente: apaga a própria janela antes de inserir.
-- ============================================================================
USE fabrica_iot;

DELETE FROM leituras
WHERE id_maquina = 'MOTOR_01'
  AND ts >= NOW() - INTERVAL 130 MINUTE;

